///|
async fn reserve_server_port(state : Json) -> Int32 {
  match field(state, "localPort") {
    Some(Json::Number(value, ..)) => value.to_int()
    _ => {
      let listener = @socket.TcpServer::TcpServer(
        @socket.Addr::parse("127.0.0.1:0"),
      )
      let port = listener.addr.port()
      listener.close()
      set_field(state, "localPort", Json::number(port.to_double()))
      port
    }
  }
}
fn devsy_args(state : Json) -> Array[String] {
  let args = []
  for name in ["home", "context"] {
    if field(state, name) is Some(Json::String(value)) {
      args.push("--" + name)
      args.push(value)
    }
  }
  args
}

///|
async fn devsy_result(
  state : Json,
  args : Array[String],
  stage : String,
) -> (Int32, String, String) {
  let environment = @env.get_env_vars()
  for name in location_variables {
    match field(field(state, "devsyEnv").unwrap(), name) {
      Some(Json::String(value)) => environment.set(name, value)
      _ => environment.remove(name)
    }
  }
  let invocation = saved_command(state)
  let logging = if devsy_progress_stage(stage) {
    ["--log-level", "debug", "--log-output", "json"]
  } else {
    []
  }
  let result = command_result(
    invocation[0],
    invocation[1:].to_owned() + devsy_args(state) + logging + args,
    stage,
    environment~,
  )
  result
}

///|
async fn devsy(state : Json, args : Array[String], stage : String) -> String {
  let (status, output, detail) = devsy_result(state, args, stage)
  guard status == 0 else {
    raise AdapterError(command_failure(stage, status, detail))
  }
  output
}

///|
fn saved_command(state : Json) -> Array[String] raise ConfigError {
  command_field(state, "recipeResult.userData").unwrap_or(["devsy"])
}

///|
fn proxy(
  state : Json,
  executable : String,
  services~ : Bool = true,
  lease~ : String = "",
) -> String raise {
  let args = ["env"]
  for name in location_variables {
    args.push("-u")
    args.push(name)
  }
  for name in location_variables {
    if field(field(state, "devsyEnv").unwrap(), name)
      is Some(Json::String(value)) {
      args.push(name + "=" + value)
    }
  }
  (args +
  [executable, "--ssh-proxy", lease] +
  saved_command(state) +
  devsy_args(state) +
  [
    "workspace",
    "ssh",
    required(state, "workspaceId"),
    "--stdio",
    "--user",
    required(state, "user"),
  ] +
  (if services { [] } else { ["--start-services=false"] }))
  .map(quote)
  .join(" ")
  .replace_all(old="%", new="%%")
}

///|
async fn ssh_args(
  state : Json,
  services~ : Bool = true,
  lease~ : String = "",
) -> Array[String] {
  [
    "-o",
    "BatchMode=yes",
    "-o",
    "ConnectTimeout=15",
    "-o",
    "ProxyCommand=" + proxy(state, adapter_executable(), services~, lease~),
    "-o",
    "StrictHostKeyChecking=no",
    "-o",
    "UserKnownHostsFile=/dev/null",
    "-o",
    "LogLevel=ERROR",
    required(state, "user") + "@" + required(state, "workspaceId") + ".devsy",
  ]
}

///|
async fn remote(state : Json, script : String, stage : String) -> String {
  command("ssh", ssh_args(state, services=false) + [script], stage)
}

///|
fn up_result(output : String) -> Json raise {
async fn lifecycle_state(mode : String) -> (Json, Json) {
  let input = @stdio.stdin.read_all()
  let payload = @json.parse(input.text())
  guard field(payload, "schemaVersion") == Some(Json::number(1)) else {
    raise AdapterError("Invalid lifecycle payload schema")
  }
  let result = match field(payload, "recipeResult") {
    Some(value) => value
    None => raise AdapterError("Missing recipeResult")
  }
  let state = match field(result, "userData") {
    Some(value) => value
    None => raise AdapterError("Missing saved adapter state")
  }
  guard field(state, "adapterVersion") == Some(Json::number(1)) else {
    raise AdapterError("Unsupported adapter state")
  }
  validate_state(state)
  match workspace(state) {
    Some(current) if field(current, "uid") == field(state, "workspaceUid") => ()
    None if mode == "destroy" => ()
    _ => raise AdapterError("Workspace missing or replaced")
  }
  (state, result)
}

///|
async fn emit_connection(
  state : Json,
  install : Bool,
  existing? : Json,
  wait_for_git~ : Bool = true,
  restart~ : Bool = false,
) -> Unit {
  let connection = if required(state, "connection") == "ssh" {
    ensure_ssh_worker(state, None, wait_for_git~, restart~)
    let target : Json = {
      "label": "Devsy",
      "host": required(state, "workspaceId") + ".devsy",
      "port": 22,
      "username": required(state, "user"),
      "proxyCommand": proxy(state, saved_proxy_executable(), services=false),
    }
    let output : Json = {
      "type": "ssh",
      "projectRoot": required(state, "projectRoot"),
      "target": target,
    }
    output
  } else if existing is Some(result) {
    let port = match field(state, "localPort") {
      Some(Json::Number(port, ..)) => port.to_int()
      _ => raise AdapterError("Missing saved tunnel port")
    }
    ensure_ssh_worker(state, Some(port), restart~)
    match field(result, "connection") {
      Some(value) => value
      None => raise AdapterError("Missing saved connection")
    }
  } else {
    server_connection(state, install)
  }
  let version = if required(state, "checkoutMode") == "provisioned-root" {
    2
  } else {
    1
  }
  let output : Json = {
    "schemaVersion": version,
    "connection": connection,
    "userData": state,
  }
  if version == 2 {
    set_field(output, "checkoutMode", Json::string("provisioned-root"))
  }
  @stdio.stdout.write(output.stringify() + "\n")
}

///|
async fn execute_inner(mode : String) -> Unit {
  notify(mode)
  let (state, previous) = if mode == "create" {
    (create_state(), Json::null())
  } else {
    lifecycle_state(mode)
  }
  match mode {
    "create" => {
      create_recording.phase = "connection"
      errdefer discard_created_workspace(state)
      codex_addon(state)
      emit_connection(state, true, wait_for_git=false)
    }
    "resume" => {
      ignore(
        devsy(
          state,
          [
            "--result-format",
            "json",
            "workspace",
            "up",
            required(state, "workspaceId"),
            "--ide-launch",
            "skip",
          ],
          "workspace-resume",
        ),
      )
      codex_addon(state)
      if required(state, "connection") == "orca-server" &&
        server_is_running(state) {
        emit_connection(state, false, existing=previous)
      } else {
        emit_connection(state, false)
      }
    }
    "reconnect" | "restart" =>
      emit_connection(
        state,
        false,
        existing=previous,
        restart=mode == "restart",
      )
    "suspend" => {
      ignore(
        devsy(
          state,
          ["workspace", "stop", required(state, "workspaceId")],
          "workspace-stop",
        ),
      )
      close_tunnel(state)
    }
    "destroy" => {
      ignore(
        devsy(
          state,
          [
            "workspace",
            "delete",
            required(state, "workspaceId"),
            "--ignore-not-found",
          ],
          "workspace-delete",
        ),
      )
      close_tunnel(state)
    }
    _ => raise AdapterError("Unknown command")
  }
  save_diagnostic(mode, "success")
  progress_message(mode + ": done (" + progress_timing(progress_started) + ")")
}

///|
fn set_field(value : Json, key : String, item : Json) -> Unit {
///|
extern "C" fn proxy_exit(code : Int32) -> Unit = "exit"

///|
fn init {
  // exec must precede the async runtime, which blocks termination signals.
  let args = @env.args()
  if args.length() > 1 &&
    args[1] == "--ssh-proxy-worker" &&
    !@adapter.prepare_ssh_proxy() {
    proxy_exit(127)
  }
  match args {
    [_, "--ssh-transport", .. command] =>
      proxy_exit(@adapter.ssh_transport(command.to_owned()))
    _ => ()
  }
}

///|
async fn main {
  let args = @env.args()
  match args {
    [_, "--ssh-proxy-worker", lease, parent, .. command] =>
      proxy_exit(@adapter.ssh_proxy_worker(command.to_owned(), lease~, parent~))
    [_, "--ssh-proxy", lease, .. command] =>
      proxy_exit(@adapter.ssh_proxy(command.to_owned(), lease~))
    [_, "--tunnel-worker", directory] => @adapter.tunnel_worker(directory)
    [_, "--version"] =>
      @stdio.stdout.write("orca-env-devsy " + @adapter.version + "\n")
    [_, "reconnect"] => @adapter.reconnect_all()
    [_, "reconnect", "--receipt"] => @adapter.execute("reconnect")
    [_, "restart"] => @adapter.reconnect_all(restart=true)
    [_, "restart", "--receipt"] => @adapter.execute("restart")
    [_, "create" | "resume" | "suspend" | "destroy" as mode] =>
      @adapter.execute(mode)
    [_, "--help"] =>
      @stdio.stdout.write(
        "Usage: orca-env-devsy <create|resume|suspend|destroy|reconnect [--receipt]|restart [--receipt]>\n",
      )
    _ => @adapter.usage_error()
  }
}

///|
async fn worker_alive(directory : String) -> Bool {
  let lock = @fs.open(
    directory + "/worker.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  !lock.try_lock(Exclusive)
}

///|
async fn tunnel_status(directory : String, status : String) -> Unit {
  let value : Json = { "status": status, "runId": recording_run_id }
  @fs.write_file(directory + "/status.tmp", value.stringify(), permission=0o600)
  @fs.rename(
    directory + "/status.tmp",
    directory + "/status.json",
    replace=true,
  )
  save_diagnostic("orca-tunnel", status)
}

///|
async fn adapter_executable() -> String {
  let name = @env.args()[0]
  if name.contains("/") {
    return @fs.realpath(name)
  }
  for directory in @env.get_env_var("PATH").unwrap_or("").split(":") {
    let path = directory.to_owned() + "/" + name
    if @fs.exists(path) {
      return @fs.realpath(path)
    }
  }
  raise AdapterError("Adapter executable is unavailable for tunnel recovery")
}

///|
async fn saved_proxy_executable() -> String {
  let directory = adapter_state_home()
  @fs.mkdir(directory, recursive=true, permission=0o700, allow_exist=true)
  let lock = @fs.open(
    directory + "/launcher.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  @async.with_timeout(10000, async fn() {
    while !lock.try_lock(Exclusive) {
      @async.sleep(10)
    }
  })
  let target = directory + "/ssh-proxy-adapter"
  let executable = adapter_executable()
  if executable == target {
    return target
  }
  save_diagnostic("ssh-proxy-launcher", "started")
  errdefer save_diagnostic(
    "ssh-proxy-launcher",
    "failed",
    error_type="filesystem",
  )
  let binary = @fs.read_file(executable).binary()
  if !@fs.exists(target) || @fs.read_file(target).binary() != binary {
    // A private executable copy survives package-manager pruning. Rename keeps
    // active proxies valid while create/resume/reconnect refresh future calls.
    let temporary = directory + "/ssh-proxy-adapter.tmp"
    defer (@fs.remove(temporary) catch { _ => () })
    @fs.write_file(temporary, binary, permission=0o700)
    @fs.rename(temporary, target, replace=true)
  }
  save_diagnostic("ssh-proxy-launcher", "success")
  target
}

///|
fn adapter_state_home() -> String raise {
  let root = match @env.get_env_var("XDG_STATE_HOME") {
    Some(value) if value != "" => value
    _ => environment("HOME") + "/.local/state"
  }
  guard root.has_prefix("/") else {
    raise AdapterError("XDG_STATE_HOME must be absolute")
  }
  root + "/orca-env-devsy"
}

///|
fn control_socket(state : Json, directory : String) -> String {
  match field(state, "socketDirectory") {
    Some(Json::String(value)) => value + "/socket"
    _ => directory + "/socket"
  }
}

///|
async fn stop_tunnel_master(
  state : Json,
  directory : String,
  verify~ : Bool = false,
) -> Unit {
  @async.with_timeout(2000, async fn() {
    ignore(
      @process.collect_output(
        "ssh",
        ssh_args(state) + ["-S", control_socket(state, directory), "-O", "exit"],
      ),
    )
  }) catch {
    _ => ()
  }
  if verify {
    @async.with_timeout(5000, async fn() {
      while true {
        let (code, _, _) = @process.collect_output(
          "ssh",
          ssh_args(state) +
          [
            "-o",
            "ProxyCommand=false",
            "-S",
            control_socket(state, directory),
            "-O",
            "check",
          ],
        )
        if code != 0 {
          break
        }
        @async.sleep(100)
      }
    })
  }
  if field(state, "socketDirectory") is Some(Json::String(socket_directory)) {
    if @fs.exists(socket_directory + "/socket") {
      @fs.remove(socket_directory + "/socket")
    }
    wait_ssh_proxy(state, "primary")
    let lease = socket_directory + "/primary-proxy.lock"
    if @fs.exists(lease) {
      @fs.remove(lease)
    }
    @fs.rmdir(socket_directory) catch {
      _ => ()
    }
  }
}

///|
async fn ensure_ssh_worker(
  state : Json,
  port : Int32?,
  wait_for_git~ : Bool = true,
  restart~ : Bool = false,
) -> Unit {
  let base = adapter_state_home() + "/tunnels"
  @fs.mkdir(base, recursive=true, permission=0o700, allow_exist=true)
  let directory = match field(state, "tunnelDirectory") {
    Some(Json::String(old)) if old.has_prefix(base + "/") && @fs.exists(old) =>
      old
    _ => {
      if restart &&
        field(state, "tunnelDirectory") is Some(Json::String(old)) &&
        @fs.exists(old) {
        let lease = @fs.open(
          old + "/startup.lock",
          mode=ReadWrite,
          create_mode=OpenOrCreate,
          permission=0o600,
        )
        defer lease.close()
        @async.with_timeout(30000, async fn() {
          while !lease.try_lock(Exclusive) {
            @async.sleep(100)
          }
        })
        let saved = if @fs.exists(old + "/state.json") {
          @json.parse(@fs.read_file(old + "/state.json").text())
        } else {
          state
        }
        guard field(saved, "workspaceUid") == field(state, "workspaceUid") else {
          raise AdapterError("Tunnel ownership changed")
        }
        restart_tunnel(saved, old)
      }
      close_tunnel(state)
      let temporary = @fs.tmpdir(prefix="oe")
      let name = temporary.split("/").to_array().last().unwrap().to_owned()
      @fs.rmdir(temporary)
      let directory = base + "/" + name
      @fs.mkdir(directory, permission=0o700)
      set_field(state, "tunnelDirectory", Json::string(directory))
      directory
    }
  }
  let lease = @fs.open(
    directory + "/startup.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lease.close()
  @async.with_timeout(30000, async fn() {
    while !lease.try_lock(Exclusive) {
      @async.sleep(100)
    }
  })
  if @fs.exists(directory + "/state.json") {
    let saved = @json.parse(@fs.read_file(directory + "/state.json").text())
    guard field(saved, "workspaceUid") == field(state, "workspaceUid") &&
      field(saved, "localPort") ==
      port.map(value => Json::number(value.to_double())) else {
      raise AdapterError("Tunnel ownership changed")
    }
    if restart {
      restart_tunnel(saved, directory)
    }
    if worker_alive(directory) {
      wait_tunnel(directory, wait_for_git~)
      return
    }
    // A dead supervisor does not invalidate its still-live SSH transport.
    // Reuse it so Devsy's old service cleanup cannot remove a new owner's helper.
    let reusable = try {
      check_tunnel(saved, directory)
      true
    } catch {
      _ => false
    }
    if reusable {
      for name in ["status.json", "git-status"] {
        if @fs.exists(directory + "/" + name) {
          @fs.remove(directory + "/" + name)
        }
      }
      spawn_tunnel_worker(directory)
      wait_tunnel(directory, wait_for_git~)
      return
    }
    stop_tunnel_master(saved, directory)
  } else if restart {
    restart_tunnel(state, directory)
  }
  let socket_directory = @fs.tmpdir(prefix="oe")
  let saved = Json::empty_object()
  for
    name in [
      "workspaceId", "workspaceUid", "user", "command", "devsyEnv", "home", "context",
      "connection",
    ] {
    if field(state, name) is Some(value) {
      set_field(saved, name, value)
    }
  }
  set_field(saved, "socketDirectory", Json::string(socket_directory))
  if port is Some(value) {
    set_field(saved, "localPort", Json::number(value.to_double()))
  }
  @fs.write_file(directory + "/state.tmp", saved.stringify(), permission=0o600)
  @fs.rename(directory + "/state.tmp", directory + "/state.json", replace=true)
  @fs.write_file(directory + "/enabled", "", permission=0o600)
  if @fs.exists(directory + "/status.json") {
    @fs.remove(directory + "/status.json")
  }
  spawn_tunnel_worker(directory)
  wait_tunnel(directory, wait_for_git~)
}

///|
async fn restart_tunnel(state : Json, directory : String) -> Unit {
  let mut phase = if worker_alive(directory) { "worker" } else { "master" }
  save_diagnostic(
    "ssh-tunnel-restart",
    "started",
    phase~,
    tunnel_directory=directory,
  )
  let mut timed_out = false
  errdefer save_diagnostic(
    "ssh-tunnel-restart",
    if timed_out {
      "timeout"
    } else {
      "failed"
    },
    phase~,
    error_type=if timed_out { "shutdown_timeout" } else { "shutdown_failed" },
    tunnel_directory=directory,
  )
  try {
    if @fs.exists(directory + "/enabled") {
      @fs.remove(directory + "/enabled")
    }
    @async.with_timeout(15000, async fn() {
      while worker_alive(directory) {
        @async.sleep(100)
      }
    })
    phase = "master"
    save_diagnostic(
      "ssh-tunnel-restart",
      "stopping",
      phase~,
      tunnel_directory=directory,
    )
    stop_tunnel_master(state, directory, verify=true)
  } catch {
    @async.TimeoutError as error => {
      timed_out = true
      raise error
    }
    error => raise error
  }
  save_diagnostic("ssh-tunnel-restart", "success", tunnel_directory=directory)
}

///|
async fn spawn_tunnel_worker(directory : String) -> Unit {
  let sink = @process.redirect_to_file("/dev/null", shared=true)
  defer sink.close()
  ignore(
    @process.spawn_orphan(
      saved_proxy_executable(),
      ["--tunnel-worker", directory],
      stdin=@process.redirect_from_file("/dev/null"),
      stdout=sink,
      stderr=sink,
    ),
  )
}

///|
pub async fn reconnect_all(restart~ : Bool = false) -> Unit {
  reconnect_all_inner(restart~) catch {
    AdapterError(message) => {
      @stdio.stderr.write("orca-env-devsy: " + message + "\n")
      save_diagnostic("reconnect", "failed")
      raise AdapterError(message)
    }
    _ => {
      @stdio.stderr.write(
        "orca-env-devsy: bulk reconnect failed; inspect local diagnostics\n",
      )
      save_diagnostic("reconnect", "failed")
      raise AdapterError("Bulk reconnect failed")
    }
  }
}

///|
async fn reconnect_all_inner(restart~ : Bool = false) -> Unit {
  notify(if restart { "restart" } else { "reconnect" })
  let base = adapter_state_home() + "/tunnels"
  if !@fs.exists(base) {
    save_diagnostic("reconnect", "success")
    return
  }
  ignore(saved_proxy_executable())
  let mut failures = 0
  let permits = @async.Semaphore(4)
  @async.with_task_group(async fn(group) {
    for name in @fs.readdir(base, sort=true) {
      let directory = base + "/" + name
      permits.acquire()
      group.spawn_bg(async fn() {
        defer permits.release()
        try {
          if @fs.kind(directory, follow_symlink=false) !=
            @fs.FileKind::Directory ||
            !@fs.exists(directory + "/enabled") {
            return
          }
          let state = @json.parse(
            @fs.read_file(directory + "/state.json").text(),
          )
          validate_state(state)
          if worker_alive(directory) {
            let current = worker_workspace(state, directory)
            guard current is Some(current) &&
              field(current, "uid") == field(state, "workspaceUid") else {
              @fs.remove(directory + "/enabled")
              save_diagnostic("reconnect", "ownership-error")
              return
            }
            if field(current, "running") != Some(Json::boolean(true)) {
              save_diagnostic("reconnect", "workspace-stopped")
              return
            }
          }
          let port = match field(state, "localPort") {
            Some(Json::Number(value, ..)) if value >= 1 &&
              value <= 65535 &&
              value == value.to_int().to_double() => Some(value.to_int())
            None if field(state, "connection") == Some(Json::string("ssh")) =>
              None
            _ => raise AdapterError("Invalid saved tunnel port")
          }
          set_field(state, "tunnelDirectory", Json::string(directory))
          ensure_ssh_worker(state, port, restart~)
          save_diagnostic("reconnect", "success")
        } catch {
          AdapterError("Tunnel workspace ownership changed") =>
            save_diagnostic("reconnect", "ownership-error")
          AdapterError("Tunnel workspace stopped") =>
            save_diagnostic("reconnect", "workspace-stopped")
          _ =>
            if @fs.exists(directory) {
              failures += 1
              save_diagnostic("reconnect", "failed")
            } else {
              save_diagnostic("reconnect", "target-removed")
            }
        }
      })
    }
  })
  guard failures == 0 else {
    raise AdapterError(
      "Some tunnels could not be restored; other targets were attempted",
    )
  }
  save_diagnostic("reconnect", "success")
}

