		format, extracted, err := gitsshsigning.ExtractGitConfiguration(ctx, workingDir)
		if err != nil {
			log.Debugf("failed to extract git configuration: %v", err)
			return command
		}
		if format != gitsshsigning.GPGFormatSSH || extracted == "" {
