	workspaceClient client2.BaseWorkspaceClient,
) string {
	if workdir != "" {
		return workdir
	}

	if workspaceFolder := resolveMergedWorkspaceFolder(
		workspaceClient,
	); workspaceFolder != "" {
		return workspaceFolder
	}

	return path.Join("/workspaces", workspaceClient.Workspace())
}

func (cmd *CredentialsServerCmd) Run(ctx context.Context, port int) error {
	runCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	ln, err := claimPort(port)
	if err != nil {
		if errors.Is(err, errPortOwnedByAnotherSession) {
			cmd.logPortOwnedByAnotherSession(ctx, port)
			return nil
		}
		return err
	}
	defer func() { _ = ln.Close() }()

	tunnelClient, err := tunnelserver.NewTunnelClient(os.Stdin, os.Stdout)
	if err != nil {
		return fmt.Errorf("error creating tunnel client: %w", err)
	}

	if _, err := tunnelClient.Ping(runCtx, &tunnel.Empty{}); err != nil {
		return fmt.Errorf("ping client: %w", err)
	}

	cmd.maybeForwardPorts(runCtx, tunnelClient)

	if err := cmd.configureDockerHelper(port); err != nil {
		return err
	}

	if err := configureGitUserLocally(runCtx, cmd.User, tunnelClient); err != nil {
		log.Warnf("error configuring git user: %v", err)
		return err
	}

	cleanupGitHelper, err := cmd.configureGitCredentialHelper(runCtx, port)
	if err != nil {
		return err
	}
	defer cleanupGitHelper()

	cleanupGitSigning := cmd.configureGitSigningKey()
	defer cleanupGitSigning()

	return credentials.RunCredentialsServerWithListener(runCtx, ln, tunnelClient, cmd.User)
}

// errPortOwnedByAnotherSession marks a bind failure as another session
// already owning the port, not a real error.
var errPortOwnedByAnotherSession = errors.New("credentials server port owned by another session")

// claimPort binds port and returns the listener, holding it exclusively so
// no other session can bind the same port until the caller closes it (or
// hands it to RunCredentialsServerWithListener). Only one session's
// credentials-server can hold this port at a time.
func claimPort(port int) (net.Listener, error) {
	addr := net.JoinHostPort("localhost", strconv.Itoa(port))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		if errors.Is(err, syscall.EADDRINUSE) {
			return nil, fmt.Errorf("%w: %w", errPortOwnedByAnotherSession, err)
		}
		return nil, fmt.Errorf("port %d not available: %w", port, err)
	}
	workingDir string,
) string {
	userSigningKey := explicitKey
	if userSigningKey == "" {
		format, extracted, err := gitsshsigning.ExtractGitConfiguration(ctx, workingDir)
		if err != nil {
			log.Debugf("failed to extract git configuration: %v", err)
			return command
		}
		if format != gitsshsigning.GPGFormatSSH || extracted == "" {
			return command
		}
		userSigningKey = extracted
	}
	encodedKey := base64.StdEncoding.EncodeToString([]byte(userSigningKey))
	command += fmt.Sprintf(" --git-user-signing-key %s", encodedKey)
	return command
}

// buildCredentialsCommand builds the credentials server command.
func buildCredentialsCommand(ctx context.Context, opts RunServicesOptions) string {
	command := fmt.Sprintf(
		"%s internal agent container credentials-server --user %s",
		shellescape.Quote(config.ContainerDevsyHelperLocation),
		shellescape.Quote(opts.User),
	)
	if opts.ConfigureGitCredentials {
		command += " --configure-git-helper"
	}
	if opts.ConfigureGitSSHSignatureHelper {
		workingDir := ""
		if opts.Workspace != nil {
			workingDir = opts.Workspace.Source.LocalFolder
		}
		command = addGitSSHSigningKey(ctx, command, opts.GitSSHSigningKey, workingDir)
	}
	if opts.ConfigureDockerCredentials {
		command += " --configure-docker-helper"
	}
	if opts.ForwardPorts {
		command += " --forward-ports"
	}
	if log.DebugEnabled() {
		command += debugFlag
	}
	return command
}

// runServicesIteration performs one iteration of the retry loop.
func runServicesIteration(
	ctx context.Context,
	opts RunServicesOptions,
	forwardedPorts []string,
	resolver PortAttributeResolver,
) error {
	stdoutReader, stdoutWriter, err := os.Pipe()
	if err != nil {
		return err
	}
	defer func() { _ = stdoutWriter.Close() }()

	stdinReader, stdinWriter, err := os.Pipe()
	if err != nil {
		_ = stdoutReader.Close()
		return err
	}
	defer func() { _ = stdinReader.Close() }()

	cancelCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	forwarder := createForwarder(opts, forwardedPorts, resolver)

	errChan := make(chan error, 1)
	go runTunnelServer(cancelCtx, cancel, tunnelServerParams{
		opts:         opts,
		stdoutReader: stdoutReader,
		stdinWriter:  stdinWriter,
		forwarder:    forwarder,
		errChan:      errChan,
	})

	writer, writerDone := log.PipeJSONStream()
	defer func() {
		_ = writer.Close()
		<-writerDone
	}()

	command := buildCredentialsCommand(ctx, opts)

	err = devssh.Run(cancelCtx, devssh.RunOptions{
		Client:  opts.ContainerClient,
		Command: command,
		Stdin:   stdinReader,
		Stdout:  stdoutWriter,
		Stderr:  writer,
	})
	if err != nil {
		// Drain errChan to allow goroutine to exit cleanly
		select {
		case <-errChan:
		default:
		}
		return err
	}
	return <-errChan
}

// RunServices forwards the ports for a given workspace and uses its SSH client
// to run the credentials server remotely and the services server locally to
// communicate with the container.
func RunServices(ctx context.Context, opts RunServicesOptions) error {
	exitAfterTimeout := getExitAfterTimeout(opts.DevsyConfig, opts.DisableIdleTimeout)

	fp := portForwardParams{
		containerClient:  opts.ContainerClient,
		extraPorts:       opts.ExtraPorts,
		exitAfterTimeout: exitAfterTimeout,
		extraListeners:   opts.ExtraListeners,
	}

	result, err := getContainerResult(ctx, fp)
	if err != nil {
		return err
	}
	forwardedPorts := forwardDevContainerPorts(ctx, fp, result)

	resolver := buildPortAttributeResolver(result)

	return retry.OnError(wait.Backoff{
		Steps:    maxRetrySteps,
		Duration: retryDuration,
		Factor:   retryFactor,
		Jitter:   retryJitter,
	}, func(err error) bool {
		return ctx.Err() == nil
	}, func() error {
		return runServicesIteration(ctx, opts, forwardedPorts, resolver)
	})
}

// buildPortAttributeResolver loads port attributes from the container result.
func buildPortAttributeResolver(result *config2.Result) PortAttributeResolver {
	if result == nil || result.MergedConfig == nil {
		return nil
	}
	mc := result.MergedConfig
	if len(mc.PortsAttributes) == 0 && mc.OtherPortsAttributes == nil {
		return nil
	}
	return NewPortAttributeResolver(mc.PortsAttributes, mc.OtherPortsAttributes)
