		return nil
	}
	githubClient, ok := client.(interface {
		GitHubCredentials(context.Context, *tunnel.Empty, ...grpc.CallOption) (*tunnel.Message, error)
	})
	if !ok {
		return json.NewEncoder(writer).Encode(map[string]string{"status": "rpc_unavailable"})
	}
