func ConfigureCredentialsContainer(userName string, port int) error {
	userHome, err := command.GetHome(userName)
	if err != nil {
		return err
	}

	configDir := os.Getenv("DOCKER_CONFIG")
	if configDir == "" {
		configDir = filepath.Join(userHome, ".docker")
	}

	return configureCredentials(userName, "#!/bin/sh", "/usr/local/bin", configDir, port)
}

const AzureContainerRegistryUsername = "00000000-0000-0000-0000-000000000000"

func configureCredentials(
	userName, shebang string,
	targetDir, configDir string,
	port int,
) error {
	binaryPath, err := os.Executable()
	if err != nil {
		return err
	}

	err = file.MkdirAll(userName, configDir, 0o755)
	if err != nil {
		return err
	}

	dockerConfig, err := config.Load(configDir)
	if err != nil {
		return err
	}

	if err := writeCredentialHelper(targetDir, binaryPath, shebang, port); err != nil {
		return err
	}

	dockerConfig.CredentialsStore = pkgconfig.BinaryName
	err = dockerConfig.Save()
	if err != nil {
		return err
	}

	err = file.Chown(userName, dockerConfig.Filename)
	if err != nil {
		return err
	}

	return nil
}

func writeCredentialHelper(targetDir, binaryPath, shebang string, port int) error {
	helperName := pkgconfig.DockerCredentialHelperName
	if runtime.GOOS == windowsOS {
		helperName += ".cmd"
	}
	credentialHelperPath := filepath.Join(targetDir, helperName)

	helperContent := buildHelperContent(binaryPath, shebang, port)

	// #nosec G306 -- executable file needs 0755 permissions
	if err := os.WriteFile(credentialHelperPath, helperContent, 0o755); err != nil {
		return fmt.Errorf("write credential helper: %w", err)
	}
	log.Debugf("Wrote docker credentials helper to %s", credentialHelperPath)

	return nil
}

func buildHelperContent(binaryPath, shebang string, port int) []byte {
	if runtime.GOOS == windowsOS {
		escapedPath := strings.ReplaceAll(binaryPath, "%", "%%")
		script := fmt.Sprintf(
			"@echo off\r\n\"%s\" internal agent docker-credentials --port %d %%*\r\n",
			escapedPath,
			port,
		)
		return []byte(script)
	}

	cmd := shellescape.QuoteCommand([]string{
		binaryPath,
		"internal",
		"agent",
		"docker-credentials",
		"--port",
		fmt.Sprintf("%d", port),
	})
	return []byte(shebang + "\n" + cmd + ` "$@"` + "\n")
}

func ConfigureCredentialsDockerless(targetFolder string, port int) (string, error) {
	dockerConfigDir := newDockerCredentialsDir(targetFolder)

	if err := preserveDockerConfig(dockerConfigDir); err != nil {
		_ = os.RemoveAll(dockerConfigDir)
		return "", err
	}

	err := configureCredentials(
		"",
		"#!/.dockerless/bin/sh",
		dockerConfigDir,
		dockerConfigDir,
		port,
	)
	if err != nil {
		_ = os.RemoveAll(dockerConfigDir)
		return "", err
	}

	err = os.Setenv("DOCKER_CONFIG", dockerConfigDir)
	if err != nil {
		_ = os.RemoveAll(dockerConfigDir)
		return "", err
	}

	err = appendToPath(dockerConfigDir)
	if err != nil {
		_ = os.RemoveAll(dockerConfigDir)
		return "", err
	}

	return dockerConfigDir, nil
}

