	if err != nil {
		_ = os.RemoveAll(dockerConfigDir)
		return "", err
	}

	return dockerConfigDir, nil
}

func getDockerConfigDir() string {
	if cfgDir := os.Getenv("DOCKER_CONFIG"); cfgDir != "" {
		return cfgDir
	}
	return config.Dir()
}

func preserveDockerConfig(dockerConfigDir string) error {
	srcDir := getDockerConfigDir()
	if err := file.MkdirAll("", dockerConfigDir, 0o750); err != nil {
		return err
	}

	// Copy config.json if it exists
	srcConfigFile := filepath.Join(srcDir, config.ConfigFileName)
	if _, err := os.Stat(srcConfigFile); err == nil {
		destConfigFile := filepath.Join(dockerConfigDir, config.ConfigFileName)
		if err := copy.File(srcConfigFile, destConfigFile, 0o600); err != nil {
			return fmt.Errorf("copy config.json: %w", err)
		}
	} else if !os.IsNotExist(err) {
		return fmt.Errorf("inspect Docker config: %w", err)
	}
	if err := preserveCliPluginsExtraDir(
		srcDir,
		filepath.Join(dockerConfigDir, config.ConfigFileName),
	); err != nil {
		return err
	}

	// Copy contexts if they exist
	srcContextsDir := filepath.Join(srcDir, "contexts")
	if _, err := os.Stat(srcContextsDir); err == nil {
		destContextsDir := filepath.Join(dockerConfigDir, "contexts")
		if err := copy.Directory(srcContextsDir, destContextsDir); err != nil {
			return fmt.Errorf("copy contexts: %w", err)
		}
	} else if !os.IsNotExist(err) {
		return fmt.Errorf("inspect Docker contexts: %w", err)
	}

	return nil
}

func preserveCliPluginsExtraDir(srcDir, configFile string) error {
	pluginDir, err := dockerCLIPluginsDir(srcDir)
	if err != nil {
		return err
	}
	if pluginDir == "" {
		return nil
	}
	dockerConfig, err := readCopiedDockerConfig(configFile)
	if err != nil {
		return err
	}
	pluginDirs, err := preservedDockerCLIPluginDirs(dockerConfig)
	if err != nil {
		return err
	}
	if slices.Contains(pluginDirs, pluginDir) {
		return nil
	}
	pluginDirs = append(pluginDirs, pluginDir)
	return writeDockerCLIPluginDirs(configFile, dockerConfig, pluginDirs)
}

func writeDockerCLIPluginDirs(
	configFile string,
	dockerConfig map[string]json.RawMessage,
	pluginDirs []string,
) error {
	pluginDirsJSON, err := json.Marshal(pluginDirs)
	if err != nil {
		return fmt.Errorf("encode Docker CLI plugin directories: %w", err)
	}
	dockerConfig["cliPluginsExtraDirs"] = pluginDirsJSON
	contents, err := json.Marshal(dockerConfig)
	if err != nil {
		return fmt.Errorf("encode copied Docker config: %w", err)
	}
	if err := os.WriteFile(configFile, contents, 0o600); err != nil {
		return fmt.Errorf("preserve Docker CLI plugin directory: %w", err)
	}
	return nil
}

func dockerCLIPluginsDir(srcDir string) (string, error) {
	pluginDir := filepath.Join(srcDir, "cli-plugins")
	if _, err := os.Stat(pluginDir); os.IsNotExist(err) {
		return "", nil
	} else if err != nil {
		return "", fmt.Errorf("inspect Docker CLI plugins: %w", err)
	}
	pluginDir, err := filepath.Abs(pluginDir)
	if err != nil {
		return "", fmt.Errorf("resolve Docker CLI plugin directory: %w", err)
	}
	return pluginDir, nil
}

func readCopiedDockerConfig(configFile string) (map[string]json.RawMessage, error) {
	path := filepath.Clean(configFile)
	// #nosec G304 -- path comes from Devsy's selected Docker config directory.
	contents, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		contents = []byte("{}")
	} else if err != nil {
		return nil, fmt.Errorf("read copied Docker config: %w", err)
	}
	var dockerConfig map[string]json.RawMessage
	if err := json.Unmarshal(contents, &dockerConfig); err != nil {
		return nil, fmt.Errorf("parse copied Docker config: %w", err)
	}
	if dockerConfig == nil {
		dockerConfig = make(map[string]json.RawMessage)
	}
	return dockerConfig, nil
}

func preservedDockerCLIPluginDirs(dockerConfig map[string]json.RawMessage) ([]string, error) {
	var pluginDirs []string
	pluginDirsJSON, ok := dockerConfig["cliPluginsExtraDirs"]
	if !ok {
		return nil, nil
	}
	if err := json.Unmarshal(pluginDirsJSON, &pluginDirs); err != nil {
		return nil, fmt.Errorf("parse Docker CLI plugin directories: %w", err)
	}
	return pluginDirs, nil
}

func ListCredentials() (*ListResponse, error) {
	retList := &ListResponse{Registries: map[string]string{}}
	// Get all of the credentials from container tools
	// i.e. podman, skopeo or others
	allContainerCredentials, err := dockerconfig.GetAllCredentials(nil)
	if err != nil {
		return nil, err
	}
	for registryHostname, auth := range allContainerCredentials {
		retList.Registries[registryHostname] = auth.Username
	}

	// get docker credentials
	// if a registry exists twice we overwrite with the docker auth
	// to avoid breaking existing behaviour
	dockerConfig, err := docker.LoadDockerConfig()
	if err != nil {
		return nil, err
	}

	allCredentials, err := dockerConfig.GetAllCredentials()
	if err != nil {
		return nil, err
	}

	for registryHostname, auth := range allCredentials {
		retList.Registries[registryHostname] = auth.Username
	}

	return retList, nil
}

func GetAuthConfig(host string) (*Credentials, error) {
	dockerConfig, err := docker.LoadDockerConfig()
	if err != nil {
		return nil, err
	}

	if host == "registry-1.docker.io" {
		host = "https://index.docker.io/v1/"
	}
	ac, err := dockerConfig.GetAuthConfig(host)
	if err != nil {
		return nil, err
	}

	ac, err = fillFromContainerCredentials(ac, host)
	if err != nil {
		return nil, err
	}

	// In case of Azure registry we need to set the azure username to a default, in case it's not set.
	if ac.Username == "" && strings.HasSuffix(ac.ServerAddress, "azurecr.io") {
		ac.Username = AzureContainerRegistryUsername
	}

	return credentialsFromAuthConfig(ac, host), nil
}

// fillFromContainerCredentials queries the containers ecosystem when the docker
// SDK returns empty credentials. Docker swallows credentials.errCredentialsNotFound,
// so an empty types.AuthConfig is the only signal we have.
func fillFromContainerCredentials(ac types.AuthConfig, host string) (types.AuthConfig, error) {
	empty := types.AuthConfig{}
	if ac != empty {
		return ac, nil
	}

	sanitizedHost := strings.TrimPrefix(strings.TrimPrefix(host, "https://"), "http://")
	dac, err := dockerconfig.GetCredentials(nil, sanitizedHost)
	if err != nil {
		return ac, err
	}
	ac.Username = dac.Username
	ac.Password = dac.Password
	ac.IdentityToken = REDACTED = host // Best approximation we have to mimic the docker type.

	return ac, nil
}

func credentialsFromAuthConfig(ac types.AuthConfig, host string) *Credentials {
	secret := ac.Password
	if ac.IdentityToken != "" {
		secret = ac.IdentityToken
	}

	return &Credentials{
		ServerURL: host,
		Username:  ac.Username,
		Secret:    secret,
	}
}
